class TaskGraph {
  constructor() {
    this.tasks = new Map();
    this.dependencies = new Map();
    this.maxConcurrency = Infinity; // Default to unlimited concurrency
  }

  setMaxConcurrency(maxConcurrency) {
    this.maxConcurrency = maxConcurrency;
  }

  totalTime() {
    const orderedTasks = this.order();
    const taskDurations = Array.from(this.tasks.values());
    const taskStartTimes = new Array(taskDurations.length).fill(0);
  }

  depend(id, onId) {
    if (!this.tasks.has(id) || !this.tasks.has(onId)) {
      throw new Error(`Unknown task id: ${id} or ${onId}`);
    }
    if (id === onId) {
      throw new Error(`Task cannot depend on itself: ${id}`);
    }
    if (!this.dependencies.has(id)) {
      this.dependencies.set(id, []);
    }
    this.dependencies.get(id).push(onId);
  }

  add(id, duration) {
    if (this.tasks.has(id)) {
      throw new Error(`Task with id ${id} already exists.`);
    }
    if (typeof duration !== 'number' || duration <= 0) {
      throw new Error(`Duration must be a positive number.`);
    }
    this.tasks.set(id, duration);
  }

  has(id) {
    return this.tasks.has(id);
  }

  size() {
    return this.tasks.size;
  }

  order() {
    const inDegree = new Map();
    const result = [];

    // Initialize in-degree for each task
    for (const task of this.tasks.keys()) {
      inDegree.set(task, 0);
    }

    // Calculate in-degrees
    for (const [task, deps] of this.dependencies.entries()) {
      for (const dep of deps) {
        if (this.detectCycle(task, dep)) {
          throw new Error(`Cycle detected: ${task} depends on ${dep}`);
        }
        inDegree.set(dep, inDegree.get(dep) + 1);
      }
    }

    // Queue tasks with zero in-degree
    const queue = [];
    for (const [task, degree] of inDegree.entries()) {
      if (degree === 0) {
        queue.push(task);
      }
    }

    // Process the queue
    while (queue.length > 0) {
      const task = queue.shift();
      result.push(task);

      if (this.dependencies.has(task)) {
        for (const dep of this.dependencies.get(task)) {
          inDegree.set(dep, inDegree.get(dep) - 1);
          if (inDegree.get(dep) === 0) {
            queue.push(dep);
          }
        }
      }
    }

    // Check for cycles
    if (result.length !== this.tasks.size) {
      throw new Error('Cycle detected in task dependencies.');
    }

    return result;
  }

  criticalPath() {
